// Version-bound owned entry: explicit resources only, no DefaultResourceLoader construction.
export async function loadOwnedExtensionSet(options) {
    if (options.clearCache) clearExtensionCache();
    const methods = DefaultResourceLoader.prototype;
    const receiver = {
        cwd: options.cwd,
        eventBus: options.eventBus,
        builtinExtensions: new Map(options.extensionFactories.filter(isBuiltinExtension).map(input => [input.name, input])),
        extensionFactories: options.extensionFactories.filter(input => !isBuiltinExtension(input)),
        resolveExtensionLoadPath: methods.resolveExtensionLoadPath,
        getExtensionPathKey: methods.getExtensionPathKey,
        loadExtensionPaths: methods.loadExtensionPaths,
        loadExtensionFactories: methods.loadExtensionFactories,
        addExtensionConflictDiagnostics: methods.addExtensionConflictDiagnostics,
        detectExtensionConflicts: methods.detectExtensionConflicts,
    };
    const paths = [...options.extensionPaths, ...options.builtinNames.map(name => `${BUILTIN_PATH_PREFIX}${name}`)];
    return methods.loadFinalExtensionSet.call(receiver, paths);
}
